    fun search(query: String): List<String> {
        if (query.isBlank()) return emptyList()
        val cleanQuery = query.lowercase().trim()
        val queryTokens = cleanQuery.split(Regex("\\s+")).filter { it.isNotBlank() }

        val exactMatches = mutableListOf<String>()
        val prefixMatches = mutableListOf<String>()
        val containsMatches = mutableListOf<String>()

        for ((keyword, emojis) in keywordMap) {
            val lowerKey = keyword.lowercase()
            if (lowerKey == cleanQuery) {
                exactMatches.addAll(emojis)
            } else if (lowerKey.startsWith(cleanQuery)) {
                prefixMatches.addAll(emojis)
            } else if (lowerKey.contains(cleanQuery) || cleanQuery.contains(lowerKey)) {
                containsMatches.addAll(emojis)
            } else if (queryTokens.any { lowerKey.contains(it) || it.contains(lowerKey) }) {
                containsMatches.addAll(emojis)
            }
        }

        val categoryMatches = categories
            .filter { it.name != "Recent" && it.name.lowercase().contains(cleanQuery) }
            .flatMap { it.emojis }

        return (exactMatches + prefixMatches + containsMatches + categoryMatches).distinct().take(60)
    }
